using System;using System.Linq;using System.IO;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CoastalPrefabValidate{static CoastalPrefabValidate(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalPrefabValidate.request")||EditorApplication.isCompiling)return;try{File.Delete("CoastalPrefabValidate.request");}catch(IOException){return;}Run();}
static bool Inside(Terrain t,Vector3 p){var origin=t.transform.position;var size=t.terrainData.size;float u=(p.x-origin.x)/size.x,v=(p.z-origin.z)/size.z;if(u<0||u>=1||v<0||v>=1)return false;return !t.terrainData.IsHole(Mathf.FloorToInt(u*512),Mathf.FloorToInt(v*512));}
static void Run(){var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain");var terrain=root.GetComponentInChildren<Terrain>();var seen=new HashSet<Mesh>();int removed=0;foreach(var f in root.GetComponentsInChildren<MeshFilter>()){bool plant=f.transform.parent&&(f.transform.parent.name.StartsWith("Pine_")||f.transform.parent.name.StartsWith("Shrub_"));if(plant||!f.sharedMesh||!seen.Add(f.sharedMesh))continue;var mesh=f.sharedMesh;var p=mesh.vertices;var ids=mesh.triangles;var keep=new List<int>();for(int i=0;i<ids.Length;i+=3){var a=f.transform.TransformPoint(p[ids[i]]);var b=f.transform.TransformPoint(p[ids[i+1]]);var c=f.transform.TransformPoint(p[ids[i+2]]);float edge=Mathf.Max((a-b).sqrMagnitude,Mathf.Max((a-c).sqrMagnitude,(b-c).sqrMagnitude));float quality=Vector3.Cross(b-a,c-a).magnitude/Mathf.Max(.0001f,edge);if(!Inside(terrain,a)||!Inside(terrain,b)||!Inside(terrain,c)||quality<.018f){removed++;continue;}keep.AddRange(new[]{ids[i],ids[i+1],ids[i+2]});}mesh.triangles=keep.ToArray();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);}foreach(var lod in root.GetComponentsInChildren<LODGroup>())lod.RecalculateBounds();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var nested=root.GetComponentsInChildren<Transform>(true).Where(t=>PrefabUtility.GetNearestPrefabInstanceRoot(t.gameObject)==t.gameObject).Select(t=>PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject)).Distinct().ToArray();int errors=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Where(m=>m).Select(m=>m.shader).Distinct().Sum(s=>ShaderUtil.GetShaderMessages(s).Count(m=>m.severity.ToString()=="Error"));File.WriteAllText("FinalEnvironmentRoadReview/CoastalPrefabValidation.txt","Nested prefab assets in scene="+nested.Length+"; detail shader errors="+errors+"; removed outside-footprint/sliver rock triangles="+removed+"; terrain native resolution="+terrain.terrainData.heightmapResolution+"; instancing="+terrain.drawInstanced+"; individual natural plant prefabs="+AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Scenes/Oasis/CoastalTerrain/Prefabs"}).Select(AssetDatabase.GUIDToAssetPath).Count(p=>Path.GetFileName(p).StartsWith("Natural ")));var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Final-Natural-Prefab-Road-Level"});capture.Invoke(null,new object[]{scene,new Vector3(365,130,680),new Vector3(333,28,568),"Final-Rounded-Terrain-Corner"});}}
